void SvMetaObject::Back2Delimiter( SvStream & rOutStm )
{
    // write no empty brackets
    sal_uInt64 nPos = rOutStm.Tell();
    rOutStm.SeekRel( -1 );
    char c = 0;
    rOutStm.ReadChar( c );

    while( rtl::isAsciiWhiteSpace( static_cast<unsigned char>(c) )
           && rOutStm.Tell() != 1 )
    {
        rOutStm.SeekRel( -2 );
        rOutStm.ReadChar( c );
    }

    if( c == ';' || c == ',' )
        rOutStm.SeekRel( -1 );
    else
        rOutStm.Seek( nPos );
}
