{
    sal_uInt32 nTokPos = rInStm.Tell();
    SvToken& rTok = rInStm.GetToken_Next();

    // read module name
    if( rTok.IsIdentifier() )
    {
        SetName( rTok.GetString() );
        return true;
    }

    rInStm.Seek( nTokPos );
    return false;
